from __future__ import annotations

from typing import Literal

ActNodeTypeFeature = Literal[
    "internet_access",
    "ip_addr",
    "node_type",
    "ports",
    "serial_number",
    "system_mac_address",
    "version",
    "ztp",
]

# Per-feature capability map for ACT node types. Only covers features currently generated by AVD.
_ACT_NODE_TYPE_FEATURES: dict[str, frozenset[ActNodeTypeFeature]] = {
    "cloudeos": frozenset({"internet_access", "ip_addr", "node_type", "serial_number", "system_mac_address", "version", "ztp"}),
    "cvp": frozenset({"ip_addr", "node_type", "version"}),
    "generic": frozenset({"ip_addr", "node_type", "version"}),
    "third-party": frozenset({"ip_addr", "node_type", "version"}),
    "tools-server": frozenset({"ip_addr", "node_type", "version"}),
    "veos": frozenset({"internet_access", "ip_addr", "node_type", "ports", "serial_number", "system_mac_address", "version", "ztp"}),
}


def act_node_type_supports_feature(act_node_type: str | None, feature: ActNodeTypeFeature) -> bool:
    """Keep ACT feature capability checks consistent across metadata and topology generation."""
    if act_node_type is None:
        return False
    return feature in _ACT_NODE_TYPE_FEATURES.get(act_node_type, frozenset())
